fn solve(queries: Vec<i8>) -> Vec<i8> {
    queries.into_iter().map(|n| {
        if n >= 4 {
            n % 2
        } else {
            4 - n
        }
    }).collect()
}

fn main() {
    // Example usage
    let queries = vec![2, 3, 4, 5, 6];
    let results = solve(queries);
    println!("{:?}", results); // Output: [2, 1, 0, 0, 0]
}